type TreatmentRequest={id:number;employeeId:number;date:string;medicine:string;quantity:string;status:string;notes:string}
type TreatmentDecision={id:number;employeeId:number;decisionNo:string;issueDate:string;startDate:string;endDate:string;renewalMonths:number;monthlyTreatment:string;status:string;notes:string;previousDecisionId?:number}
type InsuranceRecord={id:number;employeeId:number;provider:string;policyNo:string;from:string;to:string;notes:string}
type TreatmentDispense={id:number;decisionId:number;employeeId:number;month:string;dispenseDate:string;medicine:string;quantity:string;status:string;notes:string}
